const fs = require('fs');
const key = fs.readFileSync('/usr/local/etc/autoresearch-credentials/resend-api-key.txt', 'utf8').trim();
const next = new Date();
next.setMinutes(next.getMinutes() + 30);
const timeStr = next.toLocaleTimeString('en-US', { hour: '2-digit', minute: '2-digit', timeZone: 'America/Chicago' });
fetch('https://api.resend.com/emails', {
  method: 'POST',
  headers: { 'Authorization': 'Bearer ' + key, 'Content-Type': 'application/json' },
  body: JSON.stringify({
    from: 'Autoresearch ',
    to: 'ramene.anthony@gmail.com',
    subject: '🔔 Cron fires in 30 min (' + timeStr + ')',
    text: 'Autoresearch autonomous loop fires in 30 minutes at ' + timeStr + '.\n\nYou will receive the full report after it completes (~10 min run time).\n\nFleet: 52 skills | 35 perfect | 8-hour cycle'
  })
}).then(r => r.json()).then(d => console.log('Reminder: ' + (d.id || JSON.stringify(d))));
